import{_ as e,c as i,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"隐私政策","description":"qDiff 不收集你的数据。了解应用在 Mac 上读取什么，以及购买如何处理。","frontmatter":{"title":"隐私政策","description":"qDiff 不收集你的数据。了解应用在 Mac 上读取什么，以及购买如何处理。"},"headers":[],"relativePath":"zh-CN/privacy/index.md","filePath":"zh-CN/privacy/index.md","lastUpdated":1793948370000}'),o={name:"zh-CN/privacy/index.md"};function l(n,a,h,d,c,f){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to &quot;隐私政策&quot;">​</a></h1><p><em>更新日期：2026 年 11 月 6 日</em></p><p><strong>简单说：qDiff 不收集任何个人信息。</strong> 它是一个本地工具，你的文件始终留在 你的 Mac 上。</p><h2 id="qdiff-会读取什么" tabindex="-1">qDiff 会读取什么 <a class="header-anchor" href="#qdiff-会读取什么" aria-label="Permalink to &quot;qDiff 会读取什么&quot;">​</a></h2><p>qDiff 只打开你在应用里主动选择的文件与文件夹，并在本机完成比较、把结果显示 给你。如果你授权过某个文件夹，这份授权只是为了方便下次使用，随时可以在设置里 取消。我们不会上传任何内容。</p><h2 id="我们不做的事" tabindex="-1">我们不做的事 <a class="header-anchor" href="#我们不做的事" aria-label="Permalink to &quot;我们不做的事&quot;">​</a></h2><ul><li>不收集姓名、邮箱、使用统计。</li><li>不跨应用或跨网站追踪你。</li><li>不要求注册账号或登录。</li><li>不展示广告，也不含数据统计或第三方追踪。</li><li>不把你的文件同步或备份到任何服务器。</li></ul><h2 id="关于联网" tabindex="-1">关于联网 <a class="header-anchor" href="#关于联网" aria-label="Permalink to &quot;关于联网&quot;">​</a></h2><p>qDiff 离线可用。唯一可选的网络请求来自应用内「更多应用」页面，它只会读取一份 公开的应用列表；这个请求不包含任何关于你、你的文件或设备的信息，也不会回传 使用数据。</p><h2 id="关于购买" tabindex="-1">关于购买 <a class="header-anchor" href="#关于购买" aria-label="Permalink to &quot;关于购买&quot;">​</a></h2><p>可选的一次性购买完全由 Mac App Store 与你的 Apple ID 处理，我们看不到你的 支付信息。你可以在应用内的设置里随时恢复购买。</p><h2 id="关于本网站" tabindex="-1">关于本网站 <a class="header-anchor" href="#关于本网站" aria-label="Permalink to &quot;关于本网站&quot;">​</a></h2><p>本站是静态页面，没有登录、没有访问统计、没有广告 Cookie。打开页面不需要向我们 提供任何信息。</p><h2 id="儿童" tabindex="-1">儿童 <a class="header-anchor" href="#儿童" aria-label="Permalink to &quot;儿童&quot;">​</a></h2><p>qDiff 不面向儿童，也不会有意收集任何人的信息。</p><h2 id="变更" tabindex="-1">变更 <a class="header-anchor" href="#变更" aria-label="Permalink to &quot;变更&quot;">​</a></h2><p>如果政策有调整，我们会更新本页和上面的日期；涉及应用读取内容的变更，也会在 应用内说明。</p><h2 id="联系" tabindex="-1">联系 <a class="header-anchor" href="#联系" aria-label="Permalink to &quot;联系&quot;">​</a></h2><p>对隐私有疑问，写信到 <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>。</p>',19)])])}const q=e(o,[["render",l]]);export{p as __pageData,q as default};
